/** 
 * Runs equals and serialization test on the return values. <p>Test fails if default value cannot be determined for a constructor or factory method parameter, or if the constructor or factory method throws exception.
 * @return this tester
 */
public FactoryMethodReturnValueTester testEqualsAndSerializable() throws Exception {
  for (  Invokable<?,?> factory : getFactoriesToTest()) {
    try {
      testEqualsUsing(factory);
      Object instance=instantiate(factory);
      if (instance != null) {
        SerializableTester.reserializeAndAssert(instance);
      }
    }
 catch (    FactoryMethodReturnsNullException e) {
    }
 catch (    ParameterNotInstantiableException e) {
      // skip factory; unable to instantiate parameter
    }
  }
  return this;
}
